    '/biology/neuron-lab/': { min: 25, goals: ['Run a real reconstructed neuron and read voltage at any compartment', 'Explain how A-type K⁺ and Ih shape back-propagating spikes and EPSPs', 'Compare the model with published measurements'], first: 'Pick a CA1 cell, inject current at the soma, and click a distal dendrite to record there.', pre: [['/workbench/morphology/', 'Morphology workbench'], ['/biology/action-potential/', 'Action potential up close']], next: ['/biology/circuit-builder/', 'Circuit builder'],
      q: [{ q: 'Blocking A-type K⁺ channels in CA1 dendrites makes back-propagating action potentials…', o: ['smaller', 'larger in distal dendrites', 'unchanged'], a: 1, why: 'KA density rises with distance and normally damps bAPs (Hoffman et al. 1997).' }, { q: 'Ih density increasing along the apical dendrite mainly…', o: ['speeds up distal EPSPs and normalises their timing at the soma', 'slows all EPSPs', 'generates spikes'], a: 0, why: 'Ih shortens the local time constant distally, reducing location dependence of EPSP time course (Magee 1999).' }, { q: 'Why is a single “soma” model not enough for dendritic questions?', o: ['It has no capacitance', 'Voltage attenuates and filters along dendrites, so location matters', 'It cannot spike'], a: 1, why: 'Cable properties make EPSPs and bAPs location-dependent.' }] },
